pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipient, uint256 initialReward) public {
        vm.assume(recipient != address(0));
        uint256 amt = bound(initialReward, 0, 1 ether);

        vm.deal(address(this), amt);

        AcceptingRecipient r = new AcceptingRecipient();

        vm.deal(address(c), 100);

        c.getFirstWithdrawalBonus(address(r));

        bool ok;
        try c.withdrawReward(address(r)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract AcceptingRecipient {
    receive() external payable {}
}
